ALTER TABLE public.services ALTER COLUMN intervalo_retorno_dias SET DEFAULT NULL;
CREATE OR REPLACE FUNCTION public.service_return_defaults() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE n text:=translate(lower(NEW.name),'ãáàâéêíóôõúç','aaaaeeiooouc'); d integer:=30; BEGIN IF n ~ 'progressiva|botox|selagem' THEN IF NEW.intervalo_retorno_dias IS NULL THEN NEW.regra_cliente:='progressiva'; END IF; d:=30; ELSIF n ~ 'mecha|luzes' THEN d:=60; ELSIF n ~ 'sobrancelha' THEN d:=15; ELSIF n ~ 'raiz|coloracao|tintura' THEN d:=20; ELSIF n ~ 'unha|mao|\mpe\M|alongamento|esmaltacao|manicure|pedicure' THEN d:=14; ELSIF n ~ 'corte' THEN d:=45; END IF; IF NEW.intervalo_retorno_dias IS NULL THEN NEW.intervalo_retorno_dias:=d; END IF; RETURN NEW; END $$;
CREATE FUNCTION public.link_appointment_client() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p text; c uuid; BEGIN IF NEW.salon_client_id IS NULL AND length(regexp_replace(coalesce(NEW.client_whatsapp,''),'[^0-9]','','g'))>=10 THEN p:=regexp_replace(NEW.client_whatsapp,'[^0-9]','','g'); IF length(p) IN (10,11) THEN p:='55'||p; END IF; IF p ~ '^55[0-9]{10,11}$' THEN PERFORM pg_advisory_xact_lock(hashtextextended(NEW.salon_id::text,1)); SELECT id INTO c FROM public.salon_clients WHERE salon_id=NEW.salon_id AND (CASE WHEN length(regexp_replace(whatsapp,'[^0-9]','','g')) IN (10,11) THEN '55'||regexp_replace(whatsapp,'[^0-9]','','g') ELSE regexp_replace(whatsapp,'[^0-9]','','g') END)=p ORDER BY id LIMIT 1; IF c IS NULL THEN INSERT INTO public.salon_clients(salon_id,name,whatsapp,consent) VALUES(NEW.salon_id,NEW.client_name,p,false) RETURNING id INTO c; END IF; NEW.salon_client_id:=c; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER aa_link_appointment_client BEFORE INSERT OR UPDATE OF client_whatsapp ON public.appointments FOR EACH ROW EXECUTE FUNCTION public.link_appointment_client();
CREATE OR REPLACE VIEW public.service_return_targets WITH (security_invoker=true) AS WITH history AS (SELECT salon_id,salon_client_id client_id,service_id,(starts_at AT TIME ZONE 'America/Sao_Paulo')::date visited_on FROM public.appointments WHERE status='finalizado' AND salon_client_id IS NOT NULL AND service_id IS NOT NULL UNION ALL SELECT i.salon_id,i.client_id,i.service_id,i.visited_on FROM public.imported_client_visits i WHERE NOT EXISTS(SELECT 1 FROM public.appointments a WHERE a.salon_id=i.salon_id AND a.salon_client_id=i.client_id AND a.service_id=i.service_id AND a.status='finalizado' AND (a.starts_at AT TIME ZONE 'America/Sao_Paulo')::date=i.visited_on)), stats AS (SELECT salon_id,client_id,service_id,count(*) visits,min(visited_on) first_visit,max(visited_on) last_visit FROM history GROUP BY salon_id,client_id,service_id), rules AS (SELECT h.*,s.name service, CASE WHEN s.regra_cliente='progressiva' AND h.visits>3 AND h.last_visit>(h.first_visit+interval '3 months')::date THEN s.intervalo_cliente_antiga_dias ELSE s.intervalo_retorno_dias END interval_days FROM stats h JOIN public.services s ON s.id=h.service_id AND s.salon_id=h.salon_id) SELECT *,last_visit+interval_days next_return FROM rules;